(() => {
 const select=document.getElementById('areaSelect'),search=document.getElementById('areaSearch'),message=document.getElementById('datasetStatus'),content=document.getElementById('datasetContent');
 let areas=[],chosen=new URLSearchParams(location.search).get('city')||'',version=0;
 const esc=value=>String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
 const normalize=value=>String(value).toLocaleLowerCase('pl').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/ł/g,'l');
 const date=value=>value?new Date(value).toLocaleString('pl-PL'):'Brak informacji';
 function renderOptions(){const query=normalize(search.value);select.innerHTML='<option value="">Polska — wszystkie obszary</option>'+areas.filter(area=>area.id===chosen||normalize(area.name+' '+area.id).includes(query)).map(area=>`<option value="${area.id}">${esc(area.name)} · ${area.id}</option>`).join('');select.value=chosen;}
 async function load(){const request=++version;message.textContent='Ładowanie otwartego rejestru…';content.hidden=true;try{const response=await fetch('/api/dataset'+(chosen?'?city='+encodeURIComponent(chosen):''));if(!response.ok)throw Error('Nie udało się pobrać rejestru. Spróbuj ponownie.');const dataset=await response.json();if(request!==version)return;content.innerHTML=`<div class="dataset-heading"><div><span class="dataset-kicker">${esc(dataset.area?'TERC '+dataset.area.id:'ZBIÓR OGÓLNOPOLSKI')}</span><h2>${esc(dataset.title)}</h2><p>${dataset.records.toLocaleString('pl-PL')} rekordów AED</p></div><div class="dataset-downloads"><a href="${esc(dataset.downloads.json)}">JSON Warszawa</a><a href="${esc(dataset.downloads.geojson)}">GeoJSON</a><a href="${esc(dataset.downloads.csv)}">CSV</a></div></div><section class="dataset-responsibility" aria-labelledby="responsibilityTitle"><h3 id="responsibilityTitle">Odpowiedzialny dostawca zbioru</h3><strong>${esc(dataset.responsibility.label)}</strong><p>${dataset.responsibility.status==='declared'?'Organizacja wskazana na podstawie deklaracji administratora. Rejestracja zbioru w dane.gov.pl nie została potwierdzona.':'Nie wyznaczono organizacji odpowiedzialnej za zbiór wynikowy. Poniżej podajemy wydawców poszczególnych źródeł.'}</p><p>Zatwierdzenie przez administratora jest decyzją o publikacji w aplikacji. Nie potwierdza weryfikacji terenowej AED ani przyjęcia odpowiedzialności przez organizację.</p></section><h3>Źródła i aktualność</h3><div class="dataset-table"><table><thead><tr><th>Wydawca źródła</th><th>Licencja</th><th>Sprawdzono źródło</th><th>Opublikowano aktualizację</th></tr></thead><tbody>${dataset.sources.map(source=>`<tr><td><strong>${esc(source.publisher)}</strong><small>${esc(source.title)}</small>${source.refreshStatus==='delayed'?'<small>Odświeżanie opóźnione — udostępniamy ostatnią opublikowaną wersję.</small>':''}</td><td>${esc(source.license?.name||'Warunki wymagają doprecyzowania')}</td><td>${date(source.lastCheckedAt)}</td><td>${date(source.lastPublishedAt)}</td></tr>`).join('')}</tbody></table></div><div class="dataset-api"><h3>Stały adres danych</h3><code>${esc(location.origin+dataset.downloads.json)}</code><p>Wersja struktury: ${esc(dataset.schema_version)} · <a href="/api/schema">JSON Schema</a></p></div>`;content.hidden=false;message.textContent='';}
 catch(error){if(request===version)message.textContent=error.message;}}
 select.onchange=()=>{chosen=select.value;const url=new URL(location.href);if(chosen)url.searchParams.set('city',chosen);else url.searchParams.delete('city');history.pushState(null,'',url.pathname+url.search);load();};search.oninput=renderOptions;
 window.addEventListener('popstate',()=>{chosen=new URLSearchParams(location.search).get('city')||'';renderOptions();load();});
 (async()=>{try{const response=await fetch('/api/areas');if(!response.ok)throw Error('Nie udało się pobrać listy gmin.');areas=(await response.json()).areas;if(chosen&&!areas.some(area=>area.id===chosen))throw Error('Dane wybranej gminy są jeszcze przygotowywane.');renderOptions();await load();}catch(error){message.textContent=error.message;}})();
})();
